import logging
from . import bus, adxl345, bulk_sensor
REG_LIS2DW_WHO_AM_I_ADDR = 15
REG_LIS2DW_CTRL_REG1_ADDR = 32
REG_LIS2DW_CTRL_REG2_ADDR = 33
REG_LIS2DW_CTRL_REG3_ADDR = 34
REG_LIS2DW_CTRL_REG6_ADDR = 37
REG_LIS2DW_STATUS_REG_ADDR = 39
REG_LIS2DW_OUT_XL_ADDR = 40
REG_LIS2DW_OUT_XH_ADDR = 41
REG_LIS2DW_OUT_YL_ADDR = 42
REG_LIS2DW_OUT_YH_ADDR = 43
REG_LIS2DW_OUT_ZL_ADDR = 44
REG_LIS2DW_OUT_ZH_ADDR = 45
REG_LIS2DW_FIFO_CTRL = 46
REG_LIS2DW_FIFO_SAMPLES = 47
REG_MOD_READ = 128
LIS2DW_DEV_ID = 68
FREEFALL_ACCEL = 9.80665
SCALE = FREEFALL_ACCEL * 1.952 / 4
BATCH_UPDATES = 0.1

class LIS2DW:

    def __init__(self, config):
        self.printer = config.get_printer()
        adxl345.AccelCommandHelper(config, self)
        self.axes_map = adxl345.read_axes_map(config, SCALE, SCALE, SCALE)
        self.data_rate_default = config.getint("rate", 1600)
        self.data_rate = self.data_rate_default
        self.spi = bus.MCU_SPI_from_config(config, 3, default_speed=5000000)
        self.mcu = mcu = self.spi.get_mcu()
        self.oid = oid = mcu.create_oid()
        self.query_lis2dw_cmd = None
        mcu.add_config_cmd("config_lis2dw oid=%d spi_oid=%d" % (
         oid, self.spi.get_oid()))
        mcu.add_config_cmd(("query_lis2dw oid=%d rest_ticks=0" % (
         oid,)),
          on_restart=True)
        mcu.register_config_callback(self._build_config)
        chip_smooth = self.data_rate * BATCH_UPDATES * 2
        self.ffreader = bulk_sensor.FixedFreqReader(mcu, chip_smooth, "<hhh")
        self.last_error_count = 0
        self.batch_bulk = bulk_sensor.BatchBulkHelper(self.printer, self._process_batch, self._start_measurements, self._finish_measurements, BATCH_UPDATES)
        self.name = config.get_name().split()[-1]
        hdr = ('time', 'x_acceleration', 'y_acceleration', 'z_acceleration')
        self.batch_bulk.add_mux_endpoint("lis2dw/dump_lis2dw", "sensor", self.name, {"header": hdr})

    def _build_config(self):
        cmdqueue = self.spi.get_command_queue()
        self.query_lis2dw_cmd = self.mcu.lookup_command("query_lis2dw oid=%c rest_ticks=%u",
          cq=cmdqueue)
        self.ffreader.setup_query_command("query_lis2dw_status oid=%c", oid=(self.oid),
          cq=cmdqueue)

    def read_reg(self, reg):
        params = self.spi.spi_transfer([reg | REG_MOD_READ, 0])
        response = bytearray(params["response"])
        return response[1]

    def set_reg(self, reg, val, minclock=0):
        self.spi.spi_send([reg, val & 255], minclock=minclock)
        stored_val = self.read_reg(reg)
        if stored_val != val:
            raise self.printer.command_error("Failed to set LIS2DW register [0x%x] to 0x%x: got 0x%x. This is generally indicative of connection problems (e.g. faulty wiring) or a faulty lis2dw chip." % (
             reg, val, stored_val))

    def start_internal_client(self):
        aqh = adxl345.AccelQueryHelper(self.printer)
        self.batch_bulk.add_client(aqh.handle_batch)
        return aqh

    def _convert_samples(self, samples):
        ((x_pos, x_scale), (y_pos, y_scale), (z_pos, z_scale)) = self.axes_map
        count = 0
        for (ptime, rx, ry, rz) in samples:
            raw_xyz = (
             rx, ry, rz)
            x = round(raw_xyz[x_pos] * x_scale, 6)
            y = round(raw_xyz[y_pos] * y_scale, 6)
            z = round(raw_xyz[z_pos] * z_scale, 6)
            samples[count] = (round(ptime, 6), x, y, z)
            count += 1

    def _start_measurements(self):
        try:
            dev_id = self.read_reg(REG_LIS2DW_WHO_AM_I_ADDR)
            logging.info("lis2dw_dev_id: %x", dev_id)
            if dev_id != LIS2DW_DEV_ID:
                raise self.printer.command_error("Invalid lis2dw id (got %x vs %x).\nThis is generally indicative of connection problems\n(e.g. faulty wiring) or a faulty lis2dw chip." % (
                 dev_id, LIS2DW_DEV_ID))
            self.set_reg(REG_LIS2DW_CTRL_REG6_ADDR, 52)
            self.set_reg(REG_LIS2DW_FIFO_CTRL, 192)
            self.set_reg(REG_LIS2DW_CTRL_REG1_ADDR, 148)
            rest_ticks = self.mcu.seconds_to_clock(4.0 / self.data_rate)
            self.query_lis2dw_cmd.send([self.oid, rest_ticks])
            self.set_reg(REG_LIS2DW_FIFO_CTRL, 192)
            logging.info("LIS2DW starting '%s' measurements", self.name)
        except self.printer.command_error as e:
            try:
                raise self.printer.command_error("Failed to set LIS2DW register start measurements")
            finally:
                e = None
                del e

        else:
            self.ffreader.note_start()
            self.last_error_count = 0

    def _finish_measurements(self):
        error_record = None
        try:
            self.set_reg(REG_LIS2DW_FIFO_CTRL, 0)
        except self.printer.command_error as e:
            try:
                error_record = e
            finally:
                e = None
                del e

        else:
            self.query_lis2dw_cmd.send_wait_ack([self.oid, 0])
            self.ffreader.note_end()
            logging.info("LIS2DW finished '%s' measurements", self.name)
            try:
                self.set_reg(REG_LIS2DW_FIFO_CTRL, 0)
            except self.printer.command_error as e:
                try:
                    error_record = e
                finally:
                    e = None
                    del e

            else:
                if error_record is not None:
                    raise error_record

    def _process_batch(self, eventtime):
        samples = self.ffreader.pull_samples()
        self._convert_samples(samples)
        if not samples:
            return {}
        return {'data':samples,  'errors':self.last_error_count,  'overflows':(self.ffreader.get_last_overflows)()}

    def set_sample_rate(self, new_rate):
        self.data_rate = new_rate
        logging.info("LIS2DW set_sample_rate: %d" % self.data_rate)
        logging.info("chip_clock_smooth(before modification): %d" % self.ffreader.clock_sync.chip_clock_smooth)
        chip_smooth = self.data_rate * BATCH_UPDATES * 2
        self.ffreader.clock_sync.chip_clock_smooth = chip_smooth
        logging.info("chip_clock_smooth(after modification): %d" % self.ffreader.clock_sync.chip_clock_smooth)


def load_config(config):
    return LIS2DW(config)


def load_config_prefix(config):
    return LIS2DW(config)

